package ex0409;

public class Ex04tripleoperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num1 = 3;
		int num2 = 10;
		
		//삼항연산자 문법
		// 조건식 ? true 일 경우 : false 경우
		
		System.out.println(num1 > num2 ? num1+"가 더 큽니다": num2+"가 더 큽니다");
		
		
	}

}
